    text-align: center;
    padding: 60px 0 40px;
    border-bottom: 1px solid {grid_color};
    margin-bottom: 48px;
  }}
  .header h1 {{
    font-size: 2.2rem;
    font-weight: 700;
    color: #fff;
    margin-bottom: 12px;
    letter-spacing: -0.02em;
  }}
  .header .subtitle {{
    font-size: 1.05rem;
    color: {text_secondary};
    font-weight: 300;
    max-width: 700px;
    margin: 0 auto;
  }}
  .header .meta {{
    font-size: 0.82rem;
    color: {text_secondary};
    margin-top: 16px;
    opacity: 0.7;
  }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 48px;
  }}
  .kpi-card {{
    background: {card_bg};
    border: 1px solid {grid_color};
    border-radius: 10px;
    padding: 20px 16px;
    text-align: center;
  }}
  .kpi-card .kpi-label {{
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: {text_secondary};
    margin-bottom: 8px;
  }}
  .kpi-card .kpi-value {{
    font-size: 1.5rem;
    font-weight: 700;
    color: #fff;
  }}
  .kpi-card .kpi-sub {{
    font-size: 0.78rem;
    color: {accent2};
    margin-top: 4px;
  }}
  .section {{
    margin-bottom: 56px;
  }}
  .section h2 {{
    font-size: 1.4rem;
    font-weight: 600;
    color: #fff;
    margin-bottom: 8px;
    letter-spacing: -0.01em;
    padding-bottom: 12px;
    border-bottom: 2px solid {accent};
    display: inline-block;
  }}
  .section h3 {{
    font-size: 1.1rem;
    font-weight: 500;
    color: {accent2};
    margin: 24px 0 12px;
  }}
  .section p {{
    font-size: 0.95rem;
    color: {text_secondary};
    margin-bottom: 16px;
    max-width: 900px;
  }}
  .chart-container {{
    background: {card_bg};
    border: 1px solid {grid_color};
    border-radius: 10px;
    padding: 20px;
    margin: 20px 0;
    overflow-x: auto;
  }}
  .chart-title {{
    font-size: 0.85rem;
    font-weight: 500;
    color: {text_secondary};
    margin-bottom: 12px;
    text-align: center;
  }}
  .decade-table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.9rem;
  }}
  .decade-table th {{
    background: #1a2744;
    color: {accent2};
    padding: 12px 14px;
    text-align: right;
    font-weight: 500;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-bottom: 2px solid {accent};
  }}
  .decade-table th:first-child {{ text-align: left; }}
  .decade-table td {{
    padding: 11px 14px;
    text-align: right;
    border-bottom: 1px solid {grid_color};
    color: {text_primary};
  }}
  .decade-table td:first-child {{
    text-align: left;
    font-weight: 600;
    color: #fff;
  }}
  .decade-table tr:hover {{ background: rgba(79,156,247,0.06); }}
  .decade-table .highlight {{ background: rgba(245,158,11,0.1); }}
  .stats-grid {{
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin: 16px 0;
  }}
  .stat-item {{
    background: {card_bg};
    border: 1px solid {grid_color};
    border-radius: 8px;
    padding: 16px;
  }}
  .stat-item .stat-label {{
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: {text_secondary};
  }}
  .stat-item .stat-value {{
    font-size: 1.25rem;
    font-weight: 600;
    color: #fff;
    margin-top: 4px;
  }}
  .two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    align-items: start;
  }}
  .shock-list {{
    list-style: none;
    margin: 16px 0;
  }}
  .shock-list li {{
    padding: 12px 16px;
    border-left: 3px solid {accent};
    background: {card_bg};
    margin-bottom: 8px;
    border-radius: 0 6px 6px 0;
  }}
  .shock-list li .shock-date {{
    font-size: 0.75rem;
    color: {accent2};
    font-weight: 500;
  }}
  .shock-list li .shock-desc {{
    font-size: 0.9rem;
    color: {text_primary};
    margin-top: 2px;
  }}
  .shock-list li .shock-data {{
    font-size: 0.82rem;
    color: {text_secondary};
    margin-top: 4px;
  }}
  .positive {{ color: {positive_color}; }}
  .negative {{ color: {negative_color}; }}
  .footer {{
    text-align: center;
    padding: 40px 0 20px;
    border-top: 1px solid {grid_color};
    margin-top: 40px;
    font-size: 0.8rem;
    color: {text_secondary};
    opacity: 0.6;
  }}
  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(3, 1fr); }}
    .two-col {{ grid-template-columns: 1fr; }}
    .stats-grid {{ grid-template-columns: repeat(2, 1fr); }}
  }}
  @media (max-width: 600px) {{
    .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .stats-grid {{ grid-template-columns: 1fr; }}
    .header h1 {{ font-size: 1.5rem; }}
  }}
</style>
</head>
<body>
<div class="report">

  <div class="header">
    <h1>Global Crude Oil Price Trends</h1>
    <div class="subtitle">A comprehensive trend analysis of monthly crude oil prices spanning over five decades, identifying key price regimes, shocks, and long-term patterns.</div>
    <div class="meta">Dataset: {N} monthly observations &middot; January 1970 – March 2026 &middot; Prices in USD/bbl (nominal)</div>
  </div>

  <!-- KPI Cards -->
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-label">Overall Price Range</div>
      <div class="kpi-value">${price_range:.2f}</div>
      <div class="kpi-sub">${min_price:.2f} – ${max_price:.2f}</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">CAGR (1970–2026)</div>
      <div class="kpi-value">{cagr*100:.2f}%</div>
      <div class="kpi-sub">${prices[0]:.2f} → ${prices[-1]:.2f}</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Max MoM Change</div>
      <div class="kpi-value">{max_mom_pct['pct']:+.1f}%</div>
      <div class="kpi-sub">{max_mom_pct['date']}</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Highest Avg Decade</div>
      <div class="kpi-value">{highest_decade}</div>
      <div class="kpi-sub">${decade_stats[highest_decade]['mean']:.2f}/bbl avg</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Price Std Dev</div>
      <div class="kpi-value">${std_dev:.2f}</div>
      <div class="kpi-sub">CV: {std_dev/mean_price*100:.1f}%</div>
    </div>
  </div>

  <!-- Section 1: Executive Overview -->
  <div class="section">
    <h2>Executive Overview</h2>
    <p>
      This report analyzes {N} monthly crude oil price observations from January 1970 through March 2026. Over this 56-year span, nominal crude oil prices traversed a range of <strong>${price_range:.2f} per barrel</strong>, rising from a low of <strong>${min_price:.2f}</strong> ({dates[min_idx]}) to a peak of <strong>${max_price:.2f}</strong> ({dates[max_idx]}). The compound annual growth rate stands at <strong>{cagr*100:.2f}%</strong>, though this figure obscures the extreme episodic volatility that has characterized the market.
    </p>
    <p>
      The price history is defined not by smooth trends but by <strong>structural breaks</strong>: the OPEC embargo of 1973–74, the Iranian Revolution and Iran-Iraq War (1979–81), the counter-shock collapse of 1986, the Gulf War spike of 1990, the super-cycle peaking in mid-2008 at ${max_price:.2f}, the financial crisis crash, and the COVID-19 demand shock of 2020 followed by the Ukraine-driven surge in 2022. Each of these events reshaped the pricing regime for years afterward. The most recent data (2025–2026) shows prices moderating from the 2022 spike, settling in the $58–$88 range.
    </p>
  </div>

  <!-- Section 2: Long-Term Price Trajectory -->
  <div class="section">
    <h2>Long-Term Price Trajectory (1970–2026)</h2>
    <p>
      The full time series reveals a commodity that spent its first three years in near-dormancy below $2/bbl, then experienced a series of regime shifts. The 1970s saw prices leap from the $1–$3 range to nearly $40 by decade's end. The 1980s and 1990s were characterized by a gradual decline and range-bound trading. The 2000s brought an unprecedented bull market, with prices breaching $130/bbl in July 2008 before halving within months. The post-2008 era has oscillated between $30 and $120, with no sustained trend—reflecting the interplay of shale supply elasticity, OPEC+ coordination, and demand uncertainty.
    </p>

    <div class="chart-container">
      <div class="chart-title">Monthly Crude Oil Price (USD/bbl) — January 1970 to March 2026</div>
      <svg viewBox="0 0 {chart_w} {chart_h}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;">
        <defs>
          <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="{accent}" stop-opacity="0.3"/>
            <stop offset="100%" stop-color="{accent}" stop-opacity="0.02"/>
          </linearGradient>
        </defs>
        <!-- Grid lines -->
        {''.join(f'<line x1="{pad_l}" y1="{t["y"]:.1f}" x2="{chart_w - pad_r}" y2="{t["y"]:.1f}" stroke="{grid_color}" stroke-width="0.5"/>' for t in y_ticks)}
        <!-- Y-axis labels -->
        {''.join(f'<text x="{pad_l - 8}" y="{t["y"] + 4:.1f}" text-anchor="end" fill="{text_secondary}" font-size="11">${t["value"]}</text>' for t in y_ticks)}
        <!-- X-axis labels -->
        {''.join(f'<text x="{t["x"]:.1f}" y="{chart_h - 10}" text-anchor="middle" fill="{text_secondary}" font-size="11">{t["label"]}</text>' for t in x_ticks)}
        <!-- Area fill -->
        <polygon points="{pad_l},{sy(0):.1f} {polyline_pts} {sx(N-1):.1f},{sy(0):.1f}" fill="url(#areaGrad)"/>
        <!-- Line -->
        <polyline points="{polyline_pts}" fill="none" stroke="{accent}" stroke-width="1.5" stroke-linejoin="round"/>
        <!-- Event annotations -->
        {''.join(f'''
        <circle cx="{a["x"]:.1f}" cy="{a["y"]:.1f}" r="3.5" fill="{accent2}" stroke="#fff" stroke-width="0.8"/>
        <line x1="{a["x"]:.1f}" y1="{a["y"]:.1f}" x2="{a["x"]:.1f}" y2="{a["y"] + a["offset_y"]:.1f}" stroke="{accent2}" stroke-width="0.6" stroke-dasharray="2,2"/>
        <text x="{a["x"]:.1f}" y="{a["y"] + a["offset_y"] + (3 if a["offset_y"] > 0 else -6):.1f}" text-anchor="middle" fill="{accent2}" font-size="9" font-weight="500">{a["label"]}</text>
        ''' for a in event_annotations)}
        <!-- Axis labels -->
        <text x="{chart_w/2}" y="{chart_h - 0}" text-anchor="middle" fill="{text_secondary}" font-size="11">Year</text>
        <text x="18" y="{chart_h/2}" text-anchor="middle" fill="{text_secondary}" font-size="11" transform="rotate(-90,18,{chart_h/2})">USD/bbl</text>
      </svg>
    </div>
  </div>

  <!-- Section 3: Decade-by-Decade Breakdown -->
  <div class="section">
    <h2>Decade-by-Decade Breakdown</h2>
    <p>
      Aggregating prices by decade reveals how the pricing environment has shifted from the low-volatility early 1970s through the high-mean, high-volatility 2010s. Each decade carries the imprint of its defining supply-demand dynamics.
    </p>

    <div class="two-col">
      <div class="chart-container">
        <div class="chart-title">Average Crude Oil Price by Decade (USD/bbl)</div>
        <svg viewBox="0 0 {decade_chart_w} {decade_chart_h}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;">
          <!-- Grid -->
          {''.join(f'<line x1="{d_pad_l}" y1="{t["y"]:.1f}" x2="{decade_chart_w - d_pad_r}" y2="{t["y"]:.1f}" stroke="{grid_color}" stroke-width="0.5"/>' for t in d_y_ticks)}
          {''.join(f'<text x="{d_pad_l - 8}" y="{t["y"] + 4:.1f}" text-anchor="end" fill="{text_secondary}" font-size="10">${t["value"]}</text>' for t in d_y_ticks)}
          <!-- Bars -->
          {''.join(f'<rect x="{b["x"]:.1f}" y="{b["y"]:.1f}" width="{b["w"]:.1f}" height="{b["h"]:.1f}" rx="3" fill="{bar_highlight if b["label"] == highest_decade else bar_color}" opacity="{1.0 if b["label"] == highest_decade else 0.7}"/><text x="{b["x"] + b["w"]/2:.1f}" y="{b["y"] - 6:.1f}" text-anchor="middle" fill="#fff" font-size="10" font-weight="600">${b["value"]:.1f}</text><text x="{b["x"] + b["w"]/2:.1f}" y="{d_pad_t + d_plot_h + 18:.1f}" text-anchor="middle" fill="{text_secondary}" font-size="10">{b["label"]}</text>' for b in decade_bars)}
        </svg>
      </div>

      <div>
        <table class="decade-table">
          <tr>
            <th>Decade</th>
            <th>Mean</th>
            <th>Std Dev</th>
            <th>Min</th>
            <th>Max</th>
            <th>Range</th>
          </tr>
          {''.join(f'<tr class="{"highlight" if d == highest_decade else ""}"><td>{d}</td><td>${decade_stats[d]["mean"]:.2f}</td><td>${decade_stats[d]["std"]:.2f}</td><td>${decade_stats[d]["min"]:.2f}</td><td>${decade_stats[d]["max"]:.2f}</td><td>${decade_stats[d]["range"]:.2f}</td></tr>' for d in decade_names)}
        </table>
      </div>
    </div>

    <h3>1970s: The Era of Oil Shocks</h3>
    <p>
      The decade opened with prices below $2/bbl—a legacy of the postwar pricing regime controlled by multinational oil companies. The 1973 OPEC embargo tripled prices to over $12, and the Iranian Revolution (1979) pushed them past $40. Average price for the decade: <strong>${decade_stats["1970s"]["mean"]:.2f}/bbl</strong>, with a range of ${decade_stats["1970s"]["range"]:.2f}. This decade's volatility fundamentally restructured global energy economics.
    </p>

    <h3>1980s: Counter-Shock and Decline</h3>
    <p>
      Prices peaked early in the decade near $40 then entered a secular decline, culminating in the 1986 price collapse when Saudi Arabia abandoned its swing-producer role and flooded the market. Prices fell from the mid-$20s to below $10 within months. Average: <strong>${decade_stats["1980s"]["mean"]:.2f}/bbl</strong>. The decade demonstrated that supply discipline within OPEC was fragile.
    </p>

    <h3>1990s: Range-Bound Calm</h3>
    <p>
      The 1990s were comparatively tranquil, with prices oscillating between ${decade_stats["1990s"]["min"]:.2f} and ${decade_stats["1990s"]["max"]:.2f} and averaging <strong>${decade_stats["1990s"]["mean"]:.2f}/bbl</strong>. The Gulf War spike (August 1990) briefly pushed prices above $34, but the disruption was short-lived. The Asian financial crisis (1997–98) drove prices to decade lows near $11.
    </p>

    <h3>2000s: The Super-Cycle</h3>
    <p>
      Driven by surging Chinese demand, tight spare capacity, and financial speculation, prices staged an unprecedented rally from the mid-$20s in 2000 to a peak of <strong>${max_price:.2f}</strong> in July 2008. The financial crisis then triggered the largest absolute collapse in history, with prices plunging to $41.34 by December 2008—a decline of nearly $92 in five months. Average: <strong>${decade_stats["2000s"]["mean"]:.2f}/bbl</strong>.
    </p>

    <h3>2010s: Shale Revolution and OPEC+ Rebalancing</h3>
    <p>
      The decade recorded the highest average price at <strong>${decade_stats["2010s"]["mean"]:.2f}/bbl</strong>. The early years saw prices above $100 sustained by supply constraints, but the U.S. shale boom shifted the landscape. By 2014–16, OPEC's decision to maintain production triggered a price war, crashing prices from $108 to below $30. The formation of OPEC+ in late 2016 began a gradual rebalancing. Std deviation of ${decade_stats["2010s"]["std"]:.2f} reflects this broad range.
    </p>

    <h3>2020s: Pandemic, War, and Transition (Partial Decade)</h3>
    <p>
      The COVID-19 demand shock drove prices to ${decade_stats["2020s"]["min"]:.2f}/bbl in April 2020—the lowest level since 1999. The recovery was equally dramatic, with the Russia-Ukraine conflict pushing prices back above $116 in June 2022. The partial decade averages <strong>${decade_stats["2020s"]["mean"]:.2f}/bbl</strong> with a range of ${decade_stats["2020s"]["range"]:.2f}, and the most recent observations show a gradual moderation toward the $60–$70 range.
    </p>
  </div>

  <!-- Section 4: Price Volatility & Major Shocks -->
  <div class="section">
    <h2>Price Volatility &amp; Major Shocks</h2>
    <p>
      Volatility in crude oil is episodic rather than constant. Periods of extreme movement are tightly linked to discrete geopolitical or economic events. The chart below shows month-over-month percentage changes, with the largest moves highlighted.
    </p>

    <div class="chart-container">
      <div class="chart-title">Month-over-Month Percentage Change in Crude Oil Price</div>
      <svg viewBox="0 0 {vol_chart_w} {vol_chart_h}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;">
        <!-- Zero line -->
        <line x1="{vol_pad_l}" y1="{vol_sy(0):.1f}" x2="{vol_chart_w - vol_pad_r}" y2="{vol_sy(0):.1f}" stroke="{text_secondary}" stroke-width="0.8"/>
        <!-- Grid -->
        {''.join(f'<line x1="{vol_pad_l}" y1="{t["y"]:.1f}" x2="{vol_chart_w - vol_pad_r}" y2="{t["y"]:.1f}" stroke="{grid_color}" stroke-width="0.5"/>' for t in vol_y_ticks)}
        {''.join(f'<text x="{vol_pad_l - 8}" y="{t["y"] + 4:.1f}" text-anchor="end" fill="{text_secondary}" font-size="10">{t["value"]}%</text>' for t in vol_y_ticks)}
        <!-- X-axis labels -->
        {''.join(f'<text x="{t["x"]:.1f}" y="{vol_chart_h - 10}" text-anchor="middle" fill="{text_secondary}" font-size="10">{t["label"]}</text>' for t in vol_x_ticks)}
        <!-- Bars -->
        {''.join(f'<rect x="{b["x"]:.1f}" y="{b["y"]:.1f}" width="{max(b["w"], 1):.1f}" height="{b["h"]:.1f}" fill="{positive_color if b["pct"] >= 0 else negative_color}" opacity="0.7"/>' for b in vol_bars)}
      </svg>
    </div>

    <h3>Largest Price Shocks</h3>
    <ul class="shock-list">
      <li>
        <div class="shock-date">January 1974</div>
        <div class="shock-desc">OPEC Oil Embargo — largest MoM absolute increase</div>
        <div class="shock-data">Price jumped from $4.10 to $13.00 (+217.1%, +$8.90 MoM)</div>
      </li>
      <li>
        <div class="shock-date">May 1979</div>
        <div class="shock-desc">Iranian Revolution supply disruption</div>
        <div class="shock-data">Price surged from $22.43 to $33.50 (+49.4%, +$11.08 MoM)</div>
      </li>
      <li>
        <div class="shock-date">February 1986</div>
        <div class="shock-desc">Saudi price war / OPEC collapse</div>
        <div class="shock-data">Price dropped from $24.68 to $15.92 (-35.5%, -$8.77 MoM)</div>
      </li>
      <li>
        <div class="shock-date">August 1990</div>
        <div class="shock-desc">Iraq invades Kuwait — Gulf War spike</div>
        <div class="shock-data">Price jumped from $17.17 to $26.40 (+53.8%, +$9.23 MoM)</div>
      </li>
      <li>
        <div class="shock-date">September–December 2008</div>
        <div class="shock-desc">Global Financial Crisis collapse</div>
        <div class="shock-data">Price fell from $132.83 (Jul) to $41.34 (Dec) — a 68.9% decline in 5 months</div>
      </li>
      <li>
        <div class="shock-date">April 2020</div>
        <div class="shock-desc">COVID-19 demand destruction</div>
        <div class="shock-data">Price fell to ${prices[[r["date"] for r in rows].index("2020-04-01")]:.2f}/bbl from ${prices[[r["date"] for r in rows].index("2020-01-01")]:.2f} in January — a 65.8% decline over 3 months</div>
      </li>
      <li>
        <div class="shock-date">March–June 2022</div>
        <div class="shock-desc">Russia-Ukraine conflict</div>
        <div class="shock-data">Price surged to $116.80 in June from $78.07 in December 2021 — a 49.7% rise in 6 months</div>
      </li>
    </ul>

    <h3>Year-over-Year Extremes</h3>
    <div class="stats-grid">
      <div class="stat-item">
        <div class="stat-label">Largest YoY Increase</div>
        <div class="stat-value positive">+{max_yoy['pct']:.1f}%</div>
        <div style="font-size:0.82rem;color:{text_secondary};margin-top:4px;">{max_yoy['date']} (${max_yoy['from']:.2f} → ${max_yoy['to']:.2f})</div>
      </div>
      <div class="stat-item">
        <div class="stat-label">Largest YoY Decline</div>
        <div class="stat-value negative">{min_yoy['pct']:.1f}%</div>
        <div style="font-size:0.82rem;color:{text_secondary};margin-top:4px;">{min_yoy['date']} (${min_yoy['from']:.2f} → ${min_yoy['to']:.2f})</div>
      </div>
      <div class="stat-item">
        <div class="stat-label">Max MoM % Change</div>
        <div class="stat-value positive">+{max_mom_pct['pct']:.1f}%</div>
        <div style="font-size:0.82rem;color:{text_secondary};margin-top:4px;">{max_mom_pct['date']} (largest single-month gain)</div>
      </div>
    </div>
  </div>

  <!-- Section 5: Statistical Summary & Distribution -->
  <div class="section">
    <h2>Statistical Summary &amp; Distribution</h2>
    <p>
      The distribution of crude oil prices over the full dataset is right-skewed, with a long tail toward higher prices. The mean (${mean_price:.2f}) exceeds the median (${median_price:.2f}), confirming positive skew. The wide standard deviation of ${std_dev:.2f} (coefficient of variation: {std_dev/mean_price*100:.1f}%) underscores the substantial dispersion in prices over the analysis period.
    </p>

    <div class="two-col">
      <div class="chart-container">
        <div class="chart-title">Price Distribution Histogram</div>
        <svg viewBox="0 0 {hist_chart_w} {hist_chart_h}" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;">
          <!-- Grid -->
          {''.join(f'<line x1="{h_pad_l}" y1="{t["y"]:.1f}" x2="{hist_chart_w - h_pad_r}" y2="{t["y"]:.1f}" stroke="{grid_color}" stroke-width="0.5"/>' for t in h_y_ticks)}
          {''.join(f'<text x="{h_pad_l - 8}" y="{t["y"] + 4:.1f}" text-anchor="end" fill="{text_secondary}" font-size="10">{t["value"]}</text>' for t in h_y_ticks)}
          <!-- X-axis labels -->
          {''.join(f'<text x="{t["x"]:.1f}" y="{hist_chart_h - 10}" text-anchor="middle" fill="{text_secondary}" font-size="10">${t["label"]}</text>' for t in h_x_ticks)}
          <!-- Bars -->
