#!/usr/bin/env python3
"""Generate the Global Crude Oil Price Trends report."""

import csv
import math
import json
from datetime import datetime
from collections import defaultdict

# ── Load data ──────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", "r") as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append({
            "date": row["Date"],
            "price": float(row["Crude_Oil_Price"]),
        })

N = len(rows)
prices = [r["price"] for r in rows]
dates = [r["date"] for r in rows]

# ── Basic stats ────────────────────────────────────────────────────────
min_price = min(prices)
max_price = max(prices)
min_idx = prices.index(min_price)
max_idx = prices.index(max_price)
price_range = max_price - min_price
mean_price = sum(prices) / N
sorted_prices = sorted(prices)
median_price = (sorted_prices[N // 2 - 1] + sorted_prices[N // 2]) / 2 if N % 2 == 0 else sorted_prices[N // 2]

def percentile(vals, p):
    k = (len(vals) - 1) * p / 100
    f = math.floor(k)
    c = math.ceil(k)
    if f == c:
        return vals[int(k)]
    return vals[f] * (c - k) + vals[c] * (k - f)

p10 = percentile(sorted_prices, 10)
p25 = percentile(sorted_prices, 25)
p75 = percentile(sorted_prices, 75)
p90 = percentile(sorted_prices, 90)

std_dev = math.sqrt(sum((p - mean_price) ** 2 for p in prices) / N)

# CAGR: first price to last price over the total period in years
first_date = datetime.strptime(dates[0], "%Y-%m-%d")
last_date = datetime.strptime(dates[-1], "%Y-%m-%d")
total_years = (last_date - first_date).days / 365.25
cagr = (prices[-1] / prices[0]) ** (1 / total_years) - 1

# ── Month-over-month changes ──────────────────────────────────────────
mom_abs = []
mom_pct = []
for i in range(1, N):
    abs_chg = prices[i] - prices[i - 1]
    pct_chg = (prices[i] - prices[i - 1]) / prices[i - 1] * 100 if prices[i - 1] != 0 else 0
    mom_abs.append({"date": dates[i], "abs": abs_chg, "pct": pct_chg})
    mom_pct.append({"date": dates[i], "pct": pct_chg})

max_mom_abs = max(mom_abs, key=lambda x: x["abs"])
min_mom_abs = min(mom_abs, key=lambda x: x["abs"])
max_mom_pct = max(mom_pct, key=lambda x: x["pct"])
min_mom_pct = min(mom_pct, key=lambda x: x["pct"])

# ── Year-over-year changes ────────────────────────────────────────────
yoy_changes = []
for i in range(12, N):
    pct_chg = (prices[i] - prices[i - 12]) / prices[i - 12] * 100 if prices[i - 12] != 0 else 0
    yoy_changes.append({"date": dates[i], "from": prices[i - 12], "to": prices[i], "pct": pct_chg})

max_yoy = max(yoy_changes, key=lambda x: x["pct"])
min_yoy = min(yoy_changes, key=lambda x: x["pct"])

# ── Decade breakdown ──────────────────────────────────────────────────
decades = defaultdict(list)
for r in rows:
    year = int(r["date"][:4])
    decade = f"{(year // 10) * 10}s"
    decades[decade].append(r["price"])

decade_stats = {}
for decade in sorted(decades.keys()):
    dp = decades[decade]
    d_mean = sum(dp) / len(dp)
    d_std = math.sqrt(sum((p - d_mean) ** 2 for p in dp) / len(dp))
    d_min = min(dp)
    d_max = max(dp)
    decade_stats[decade] = {
        "mean": d_mean,
        "std": d_std,
        "min": d_min,
        "max": d_max,
        "range": d_max - d_min,
        "count": len(dp),
    }

highest_decade = max(decade_stats, key=lambda k: decade_stats[k]["mean"])

# ── Annual averages for chart data ────────────────────────────────────
annual = defaultdict(list)
for r in rows:
    year = int(r["date"][:4])
    annual[year].append(r["price"])

annual_avg = {y: sum(v) / len(v) for y, v in sorted(annual.items())}

# ── Generate SVG chart data points ────────────────────────────────────
# Time series chart
chart_w = 1100
chart_h = 420
pad_l, pad_r, pad_t, pad_b = 70, 30, 30, 50
plot_w = chart_w - pad_l - pad_r
plot_h = chart_h - pad_t - pad_b

x_min = 0
x_max = N - 1
y_min_chart = 0
y_max_chart = math.ceil(max_price / 20) * 20  # round up to nearest 20

def sx(i):
    return pad_l + (i / x_max) * plot_w

def sy(v):
    return pad_t + plot_h - ((v - y_min_chart) / (y_max_chart - y_min_chart)) * plot_h

# Build polyline points for main chart
polyline_pts = " ".join(f"{sx(i):.1f},{sy(prices[i]):.1f}" for i in range(N))

# Y-axis ticks
y_ticks = []
tick_step = 20
for v in range(0, int(y_max_chart) + 1, tick_step):
    y_ticks.append({"value": v, "y": sy(v)})

# X-axis ticks (every 5 years)
x_ticks = []
for i, r in enumerate(rows):
    year = int(r["date"][:4])
    month = int(r["date"][5:7])
    if month == 1 and year % 5 == 0:
        x_ticks.append({"label": str(year), "x": sx(i)})

# ── Volatility chart (MoM % change) ──────────────────────────────────
vol_chart_w = 1100
vol_chart_h = 280
vol_pad_l, vol_pad_r, vol_pad_t, vol_pad_b = 70, 30, 30, 50
vol_plot_w = vol_chart_w - vol_pad_l - vol_pad_r
vol_plot_h = vol_chart_h - vol_pad_t - vol_pad_b

mom_pcts = [m["pct"] for m in mom_pct]
vol_y_min = math.floor(min(mom_pcts) / 10) * 10 - 10
vol_y_max = math.ceil(max(mom_pcts) / 10) * 10 + 10

def vol_sx(i):
    return vol_pad_l + (i / (len(mom_pct) - 1)) * vol_plot_w

def vol_sy(v):
    return vol_pad_t + vol_plot_h - ((v - vol_y_min) / (vol_y_max - vol_y_min)) * vol_plot_h

# Build bar rectangles for volatility chart
vol_bars = []
bar_w = max(1, vol_plot_w / len(mom_pct))
for i, m in enumerate(mom_pct):
    x = vol_sx(i) - bar_w / 2
    if m["pct"] >= 0:
        y = vol_sy(m["pct"])
        h = vol_sy(0) - y
    else:
        y = vol_sy(0)
        h = vol_sy(m["pct"]) - y
    vol_bars.append({"x": x, "y": y, "w": bar_w, "h": max(h, 0.5), "pct": m["pct"]})

vol_y_ticks = []
vol_tick_step = 20
for v in range(int(vol_y_min), int(vol_y_max) + 1, vol_tick_step):
    vol_y_ticks.append({"value": v, "y": vol_sy(v)})

vol_x_ticks = []
for i, m in enumerate(mom_pct):
    year = int(m["date"][:4])
    month = int(m["date"][5:7])
    if month == 1 and year % 5 == 0:
        vol_x_ticks.append({"label": str(year), "x": vol_sx(i)})

# ── Decade comparison bar chart ────────────────────────────────────────
decade_chart_w = 700
decade_chart_h = 300
d_pad_l, d_pad_r, d_pad_t, d_pad_b = 80, 30, 30, 50
d_plot_w = decade_chart_w - d_pad_l - d_pad_r
d_plot_h = decade_chart_h - d_pad_t - d_pad_b

decade_names = sorted(decade_stats.keys())
d_max_val = max(decade_stats[d]["mean"] for d in decade_names)
d_y_max = math.ceil(d_max_val / 20) * 20

d_bar_w = d_plot_w / len(decade_names) * 0.6
d_gap = d_plot_w / len(decade_names) * 0.4

decade_bars = []
for idx, d in enumerate(decade_names):
    x = d_pad_l + idx * (d_plot_w / len(decade_names)) + d_gap / 2
    h = (decade_stats[d]["mean"] / d_y_max) * d_plot_h
    y = d_pad_t + d_plot_h - h
    decade_bars.append({"x": x, "y": y, "w": d_bar_w, "h": h, "label": d, "value": decade_stats[d]["mean"]})

d_y_ticks = []
for v in range(0, int(d_y_max) + 1, 20):
    d_y_ticks.append({"value": v, "y": d_pad_t + d_plot_h - (v / d_y_max) * d_plot_h})

# ── Distribution histogram ────────────────────────────────────────────
hist_chart_w = 700
hist_chart_h = 280
h_pad_l, h_pad_r, h_pad_t, h_pad_b = 60, 30, 30, 50
h_plot_w = hist_chart_w - h_pad_l - h_pad_r
h_plot_h = hist_chart_h - h_pad_t - h_pad_b

num_bins = 20
bin_width = (max_price - min_price) / num_bins
bins = [0] * num_bins
for p in prices:
    b = min(int((p - min_price) / bin_width), num_bins - 1)
    bins[b] += 1

h_max = max(bins)

hist_bars = []
for i, count in enumerate(bins):
    bw = h_plot_w / num_bins * 0.85
    gx = h_plot_w / num_bins * 0.15
    x = h_pad_l + i * (h_plot_w / num_bins) + gx / 2
    bar_h = (count / h_max) * h_plot_h if h_max > 0 else 0
    y = h_pad_t + h_plot_h - bar_h
    lo = min_price + i * bin_width
    hi = lo + bin_width
    hist_bars.append({"x": x, "y": y, "w": bw, "h": bar_h, "lo": lo, "hi": hi, "count": count})

h_y_ticks = []
for v in range(0, h_max + 1, max(1, h_max // 5)):
    h_y_ticks.append({"value": v, "y": h_pad_t + h_plot_h - (v / h_max) * h_plot_h if h_max > 0 else h_pad_t + h_plot_h})

h_x_ticks = []
for i in range(0, num_bins + 1, 4):
    x = h_pad_l + i * (h_plot_w / num_bins)
    h_x_ticks.append({"label": f"{min_price + i * bin_width:.0f}", "x": x})

# ── Annotate key events on the time series ────────────────────────────
key_events = [
    {"year": 1973, "month": 10, "label": "OPEC Embargo", "offset_y": -30},
    {"year": 1979, "month": 1, "label": "Iranian Revolution", "offset_y": -30},
    {"year": 1986, "month": 2, "label": "Price Collapse", "offset_y": 25},
    {"year": 1990, "month": 8, "label": "Gulf War", "offset_y": -30},
    {"year": 2008, "month": 7, "label": "Peak $132.83", "offset_y": -30},
    {"year": 2008, "month": 12, "label": "Financial Crisis", "offset_y": 25},
    {"year": 2020, "month": 4, "label": "COVID-19", "offset_y": 25},
    {"year": 2022, "month": 6, "label": "Ukraine War", "offset_y": -30},
]

event_annotations = []
for ev in key_events:
    target_date = f"{ev['year']}-{ev['month']:02d}-01"
    for i, r in enumerate(rows):
        if r["date"] == target_date:
            event_annotations.append({
                "x": sx(i),
                "y": sy(prices[i]),
                "label": ev["label"],
                "offset_y": ev["offset_y"],
                "price": prices[i],
            })
            break

# ── Build HTML ─────────────────────────────────────────────────────────

